local PVPArenaSeasonNode = Class('PVPArenaSeasonNode')

------------ import ------------
local KTool          = CS.Engine.Lib.KTool
local GetTimeHMS2    = CfUtils.GetTimeHMS2
local XLuaUtils      = CS.Engine.Lib.XLuaUtils
------------ import ------------

------------ define ------------

------------ define ------------

function PVPArenaSeasonNode:__init()
end

function PVPArenaSeasonNode:__delete()
end

function PVPArenaSeasonNode:Awake()
    ---@type PVPArenaComponent
    local pvpArenaComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
    ---@type PVPArenaEntryDojo
    local pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
    self.isAudience         = checkNumber(pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Audience
    self.pvpArenaEntryDojo  = pvpArenaEntryDojo
end

function PVPArenaSeasonNode:OnDestroy()
    self:RemoveCountdownEvent()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end

function PVPArenaSeasonNode:CreateCountdownEvent()
    if self.__EventCountDownUpdate then return end

    self.__EventCountDownUpdate = Events.AddListener(Constants.EventNames.PVPArenaCountDownUpdate, Bind(self, self.OnEventCountDownUpdate))
end

function PVPArenaSeasonNode:RemoveCountdownEvent()
    if self.__EventCountDownUpdate then
        Events.RemoveListener(Constants.EventNames.PVPArenaCountDownUpdate, self.__EventCountDownUpdate)
        self.__EventCountDownUpdate = nil
    end
end

---------------------------------------------------
--- ui logic begin --
---------------------------------------------------

function PVPArenaSeasonNode:RefreshUI(isShowActiveNode, isDisableCountdown)
    KTool.SetActive(self.ActiveNode.gameObject, isShowActiveNode)

    self.TxtState.color = XLuaUtils.HexToColor(isShowActiveNode and "#ffffff" or "#9D9B9B")

    --- 只有非参赛者并且再对阵图中才有倒计时
    if not self.isAudience then return end
    KTool.SetActive(self.TxtTime.gameObject, not isDisableCountdown)

    if isShowActiveNode and not isDisableCountdown then
        self:CreateCountdownEvent()
    else
        self:RemoveCountdownEvent()
    end
end

function PVPArenaSeasonNode:OnEventCountDownUpdate()
    self.TxtTime.text = GetTimeHMS2(self.pvpArenaEntryDojo.nextStageLeftSeconds)
end

